arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"types":"public_channel, private_channel","limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR', d)
else:
    for c in d['channels']:
        if 'incident' in c.get('name','').lower():
            print(c['id'], c['name'], 'private' if c.get('is_private') else 'public')
"

