arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"limit":200}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR', d)
else:
    for u in d['members']:
        real = u.get('profile',{}).get('real_name','')
        disp = u.get('profile',{}).get('display_name','')
        if 'leo' in (real+' '+disp).lower() or 'park' in (real+' '+disp).lower():
            print(u['id'], '|', real, '|', disp, '| deleted' if u.get('deleted') else '')
"

